import{_ as a,o as i,c as e,a3 as s}from"./chunks/framework.DhF4LrUq.js";const g=JSON.parse(`{"title":"Onboard an organization","description":"Onboard an organization - create it on the platform API and hand it to the customer's first Organization Administrator.","frontmatter":{"description":"Onboard an organization - create it on the platform API and hand it to the customer's first Organization Administrator."},"headers":[],"relativePath":"how-to/console/orgs.md","filePath":"how-to/console/orgs.md"}`),o={name:"how-to/console/orgs.md"};function n(r,t,h,l,d,p){return i(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="onboard-an-organization" tabindex="-1">Onboard an organization <a class="header-anchor" href="#onboard-an-organization" aria-label="Permalink to &quot;Onboard an organization&quot;">​</a></h1><p>Every ShipperDog organization is its own walled garden: the tenants, applications, releases, and policies inside it are invisible to every other organization. Creating one is a platform-operator task — the organization is born through the platform API, and everything after that happens in the Console.</p><div class="tip custom-block"><p class="custom-block-title">Who this is for</p><p>Platform operators only. If you received a welcome email, you are joining an organization that already exists — start with your <a href="/shipperdog/snapshot/roles/">role quickstart</a> instead.</p></div><h2 id="create-the-organization" tabindex="-1">Create the organization <a class="header-anchor" href="#create-the-organization" aria-label="Permalink to &quot;Create the organization&quot;">​</a></h2><ol><li><p>Authenticate against the platform API with a token that may create organizations (a platform administrator&#39;s).</p></li><li><p>Create the organization:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SHIPPERDOG_API</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/organizations&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PLATFORM_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Idempotency-Key: onboard-northwind-001&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;Northwind Mobile&quot;, &quot;externalId&quot;: &quot;northwind&quot;}&#39;</span></span></code></pre></div><p>The response carries the organization&#39;s <code>id</code> — quote it for every step that follows. A duplicate <code>externalId</code> is refused (<code>409 EXTERNAL_ID_TAKEN</code>); the idempotency key makes a retried create safe.</p></li><li><p>You are now the organization&#39;s first <strong>Organization Administrator</strong> — the creator&#39;s <code>ORG_ADMIN</code> membership is recorded at creation time. Sign in to the Console to finish the setup before handing it over.</p></li></ol><h2 id="add-the-customer-s-administrator" tabindex="-1">Add the customer&#39;s administrator <a class="header-anchor" href="#add-the-customer-s-administrator" aria-label="Permalink to &quot;Add the customer&#39;s administrator&quot;">​</a></h2><ol><li><p>Still as the creator, add the customer&#39;s admin as a member of the organization and assign the <code>ORG_ADMIN</code> role (the members API, <code>PUT /api/v1/organizations/{id}/members/{userId}/role</code>).</p></li><li><p>Share the Console URL and sign-in credentials with them through your usual secure channel. They sign in with email and password until <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">single sign-on</a> is configured for the organization.</p></li><li><p>Walk them through the first steps every organization needs, in order:</p><ul><li><a href="/shipperdog/snapshot/how-to/console/tenants">Create the first tenants</a></li><li><a href="/shipperdog/snapshot/how-to/console/apps">Register the first application</a></li><li><a href="/shipperdog/snapshot/roles/tenant-admin">Invite testers</a> into a tenant</li><li><a href="/shipperdog/snapshot/how-to/console/distribution-channels">Bind store accounts</a> if they distribute through TestFlight or Google Play</li></ul></li></ol><h2 id="what-shapes-an-organization" tabindex="-1">What shapes an organization <a class="header-anchor" href="#what-shapes-an-organization" aria-label="Permalink to &quot;What shapes an organization&quot;">​</a></h2><p>Once it exists, the organization&#39;s settings live across the Console rather than on one screen:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where</th></tr></thead><tbody><tr><td>Members and organization roles</td><td>The members API (role changes audit; the last <code>ORG_ADMIN</code> guard refuses stripping the final administrator)</td></tr><tr><td>Single sign-on (OIDC, SAML)</td><td><a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO setup</a></td></tr><tr><td>User provisioning (SCIM)</td><td><a href="/shipperdog/snapshot/how-to/console/scim-provisioning">SCIM provisioning</a></td></tr><tr><td>Access narrowing (ABAC)</td><td><a href="/shipperdog/snapshot/how-to/console/abac-policies">ABAC policies</a></td></tr><tr><td>Compliance feeds</td><td><a href="/shipperdog/snapshot/how-to/console/siem-streams">SIEM streams and the audit trail</a></td></tr></tbody></table><p>Deactivating an organization later is reversible and non-destructive: memberships stay, but roles in a deactivated organization grant nothing until it is reactivated. Why organizations are hard-walled this way is covered in <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a>.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/tenants">manage tenants</a> · <a href="/shipperdog/snapshot/how-to/console/apps">register applications</a> · <a href="/shipperdog/snapshot/get-started/platform-tour">the platform tour</a></p>`,12)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
